  }
  .top-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 15px;
    color: #444;
    padding-bottom: 15px;
    border-bottom: 1px solid #eee;
  }
  .top-header .left {
    white-space: nowrap;
  }
  .top-header .right {
    display: flex;
    gap: 28px;
    align-items: center;
    white-space: nowrap;
  }
  .top-header .right span.active {
    background: #1ba0e2;
    color: #fff;
    border-radius: 14px;
    padding: 3px 14px;
  }
  .main-title {
    font-size: 30px;
    font-weight: bold;
    color: #0072bc;
    margin: 40px 0 25px 0;
