  }
  thead tr {
    background: #1ba0e2;
    color: #fff;
  }
  thead th {
    padding: 10px 12px;
    text-align: left;
    font-weight: bold;
    font-size: 14px;
  }
  thead th.num {
    text-align: right;
  }
  tbody td {
    padding: 10px 12px;
    border-bottom: 1px solid #cfe9f7;
    vertical-align: middle;
  }
  .t1 td.label {
    color: #333;
    width: 34%;
  }
  .t1 td.num {
    text-align: right;
    color: #333;
  }
